#### Problem 1: Password hashing and verification with Argon2id

**Specification.** Hash a password with Argon2id, parameters embedded in the hash, constant-ish verification, transparent upgrade of outdated parameters on successful login, and a constant-time dummy verify for nonexistent users so the response time does not reveal account existence.

```python
import hashlib, hmac, os, re
from argon2 import PasswordHasher, Type
from argon2.exceptions import VerifyMismatchError, VerificationError, InvalidHashError

ARGON2_PARAMS = dict(time_cost=3, memory_cost=65536, parallelism=4)

class PasswordService:
    def __init__(self, hasher: PasswordHasher | None = None, dummy_secret: bytes | None = None):
        self.ph = hasher or PasswordHasher(type=Type.ID, **ARGON2_PARAMS)
        # A real hash so the dummy path costs roughly the same as a real verify.
        self._dummy = self.ph.hash(dummy_secret or os.urandom(32))

    def hash(self, password: str) -> str:
        if not (12 <= len(password) <= 1024):
            raise ValueError("password length out of range")
        return self.ph.hash(password)

    def verify(self, stored_hash: str | None, password: str) -> bool:
        if stored_hash is None:
            self.ph.verify(self._dummy, password)      # burn CPU; raises
            return False
        try:
            self.ph.verify(stored_hash, password)
        except (VerifyMismatchError, VerificationError):
            return False
        except InvalidHashError:
            return False
        return True

    def needs_rehash(self, stored_hash: str) -> bool:
        try:
            return self.ph.check_needs_rehash(stored_hash, **ARGON2_PARAMS)
        except InvalidHashError:
            return True                                # legacy/unknown -> upgrade
```

The rehash-on-login path, which is how parameters are raised without a migration:

```python
def login_and_maybe_upgrade(svc: PasswordService, users, identifier: str,
                            password: str, request_meta: dict):
    user = users.find_by_identifier(identifier)
    stored = user.password_hash if user else None
    if not svc.verify(stored, password):
        raise InvalidCredentials()
    if user is None:
        raise InvalidCredentials()
    if svc.needs_rehash(stored):
        new_hash = svc.hash(password)
        users.update_password_hash(user.id, new_hash)
        audit("password.rehashed", user_id=user.id)     # params upgraded, cost spread over traffic
    return establish_session(user, request_meta)
```

**Tests that prove it.**

```python
def test_verify_rejects_wrong_password():
    svc = PasswordService()
    h = svc.hash("correct horse battery staple")
    assert svc.verify(h, "correct horse battery staple") is True
    assert svc.verify(h, "correct horse battery stapl") is False

def test_hash_is_salted():
    svc = PasswordService()
    assert svc.hash("hunter2") != svc.hash("hunter2")

def test_nonexistent_user_costs_similar_time():
    svc = PasswordService()
    real = svc.hash("x" * 20)
    t_real = timed(lambda: svc.verify(real, "wrong-password"))
    t_dummy = timed(lambda: svc.verify(None, "wrong-password"))
    assert abs(t_real - t_dummy) < 0.4 * t_real      # 40% tolerance; flaky otherwise

def test_needs_rehash_detects_weak_params():
    weak = PasswordHasher(type=Type.ID, time_cost=1, memory_cost=8192, parallelism=1)
    svc = PasswordService()
    assert svc.needs_rehash(weak.hash("hunter2")) is True
```

**Interview reasoning.** Salting is what makes rainbow tables useless; Argon2id's memory hardness is what makes GPU cracking expensive; embedded parameters make cost increases free; the dummy verify closes the timing oracle; rehash-on-login spreads the migration.

