def test_promotion_issues_a_new_id_and_deletes_the_old():
    store, db = store_with_db()
    anon, family = store.create_anonymous({"ip": "1.2.3.4"})
    authed = store.promote(anon, "u1")
    assert authed != anon
    assert store.touch(authed).user_id == "u1"
