### Solution — Infinite list with virtualization
`	sx
import { useState, useEffect, useRef, useCallback } from 'react';

function VirtualList({ items, rowHeight = 50, overscan = 6 }) {
  const containerRef = useRef<HTMLDivElement>(null);
  const [startIndex, setStartIndex] = useState(0);
  const [viewportHeight, setViewportHeight] = useState(0);

  useLayoutEffect(() => {
    const el = containerRef.current;
    if (!el) return;
    const ro = new ResizeObserver(([e]) => setViewportHeight(e.contentRect.height));
    ro.observe(el);
    const onScroll = () => {
      setStartIndex(Math.max(0, Math.floor(el.scrollTop / rowHeight) - overscan));
    };
    el.addEventListener('scroll', onScroll, { passive: true });
    onScroll();
    return () => {
      ro.disconnect();
      el.removeEventListener('scroll', onScroll);
    };
  }, [rowHeight, overscan]);

  const visibleCount = Math.ceil(viewportHeight / rowHeight) + overscan * 2;
  const slice = items.slice(startIndex, startIndex + visibleCount);
  const padTop = startIndex * rowHeight;

  return (
    <div ref={containerRef} style={{ height: '100%', overflow: 'auto' }}>
      <div style={{ height: items.length * rowHeight, position: 'relative' }}>
        <div style={{ transform: 	ranslateY(px) }}>
          {slice.map((item, i) => (
            <div key={item.id} style={{
              height: rowHeight,
              position: 'relative',
            }}>
              {item.children}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
`
