import { useState, useEffect, useRef, useCallback } from 'react';

function Tabs({ defaultValue, children, onChange }: { defaultValue?: string; onChange: (value: string) => void }) {
  const [value, setValue] = useState(defaultValue);
  const tabRefs = useRef<HTMLButtonArray>([]);
  const panelRefs = useRef<HTMLDivElement[]>([]);

  // Store refs after render
  useEffect(() => {
    const buttons = container?.querySelectorAll('button');
    const panels = container?.querySelectorAll('div');
    if (buttons) tabRefs.current = Array.from(buttons) as HTMLButtonElement[];
    if (panels) panelRefs.current = Array.from(panels) as HTMLDivElement[];
  }, []);

  const handleClick = useCallback((e: MouseEvent) => {
    const button = e.target as HTMLButtonElement;
    const value = button.getAttribute('aria-controls') || button.getAttribute('data-value');
    setValue(value);
    onChange?.(value);
  }, [onChange]);

  const handleKeyDown = useCallback((e: KeyboardEvent) => {
    if (e.key === 'ArrowRight') {
      e.preventDefault();
      const next = value === panels?.length - 1 ? 0 : panels.indexOf(value) + 1;
      setValue(panels?.[next] || '');
    } else if (e.key === 'ArrowLeft') {
      e.preventDefault();
      const prev = value === panels?.[0] ? panels.length - 1 : panels.indexOf(value) - 1;
      setValue(panels?.[prev] || '');
    } else if (e.key === 'Home') {
      e.preventDefault();
      setValue(panels?.[0] || '');
    } else if (e.key === 'End') {
      e.preventDefault();
      setValue(panels?.length - 1 >= 0 ? panels[panels.length - 1] : '');
    }
  }, []);

  return (
    <div>
      <div role="tablist" style={{ display: 'flex', gap: 8 }}>
        {children?.map((child, i) => {
          const childValue = child.props?.value || 	ab-;
          return (
            <button
              key={childValue}
              role="tab"
              aria-controls={panel-}
              aria-selected={value === childValue}
              onClick={handleClick}
              onKeyDown={handleKeyDown}
              style={{ marginRight: 8 }}
