### Solution — Data table with sorting, filtering, pagination and URL state
`	sx
function DataTable({ columns, items, onSort, onFilter, onPageChange }: {
  columns: Column[];
  items: any[];
  onSort: (columnId: string, direction: 'asc' | 'desc') => void;
  onFilter: (filter: Filter) => void;
  onPageChange: (page: number, pageSize: number) => void;
}) {
  const [state, setState] = useReducer(wizardReducer, initialState);
  const [filter, setFilter] = useState<Filter>({});
  const [sort, setSort] = useState<Sort>({ columnId: '', direction: 'asc' });
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(10);

  // URL sync
  useEffect(() => {
    const urlParams = new URLSearchParams(window.location.search);
    if (urlParams.get('page')) setPage(Number(urlParams.get('page')));
    if (urlParams.get('pageSize')) setPageSize(Number(urlParams.get('pageSize')));
    if (urlParams.get('sort')) {
      const [col, dir] = urlParams.get('sort').split('-');
      setSort({ columnId: col, direction: dir as 'asc' | 'desc' });
    }
    if (urlParams.get('filter')) {
      setFilter(JSON.parse(urlParams.get('filter')));
    }
  }, []);

  // Sync to URL
  useEffect(() => {
    const urlParams = new URLSearchParams(window.location.search);
    urlParams.set('page', page.toString());
    urlParams.set('pageSize', pageSize.toString());
    urlParams.set('sort', ${sort.columnId}-);
    urlParams.set('filter', JSON.stringify(filter));
    const newUrl = ${window.location.pathname}?;
    // Avoid infinite loop: only update if URL changed
    if (window.location.href !== newUrl) window.history.pushState({ page, sort, filter }, '', newUrl);
  }, [page, pageSize, sort, filter]);

  // Filtered, sorted, paginated data
  const sortedItems = [...items].sort((a, b) => {
    const col = columns.find(c => c.id === sort.columnId);
    if (!col) return 0;
    const aVal = a[col.accessorKey];
    const bVal = b[col.accessorKey];
    const dirCompare = sort.direction === 'asc' ? 1 : -1;
    if (typeof aVal === 'string') return aVal.localeCompare(bVal) * dirCompare;
    return (aVal > bVal ? 1 : aVal < bVal ? -1 : 0) * dirCompare;
  });

  const filteredItems = sortedItems.filter(item => {
    return Object.entries(filter).every(([key, value]) => {
      if (typeof value === 'string') return String(item[key]).includes(value);
      return String(item[key]) === String(value);
    });
  });

  const paginatedItems = filteredItems.slice((page - 1) * pageSize, page * pageSize);

  return (
    <div>
      <DataTableToolbar
        columns={columns}
        onSort={onSort}
        onFilter={onFilter}
        initialSort={sort}
        initialFilter={filter}
      />
      <DataTableBody
        columns={columns}
        items={paginatedItems}
        onPageChange={onPageChange}
        page={page}
        pageSize={pageSize}
      />
      <DataTablePagination
        page={page}
        pageSize={pageSize}
        onPageChange={onPageChange}
        totalItems={filteredItems.length}
      />
    </div>
  );
}
`
